package ioc; import java.util.ArrayList;import java.util.HashMap;import java.util.List;import java.util.Map; public final class DuplicateReport{public List<Ioc> duplicates(List<Ioc> input){Map<Ioc,Integer> counts=new HashMap<>();if(input!=null)for(Ioc i:input)counts.merge(i,1,Integer::sum);List<Ioc> out=new ArrayList<>();for(Map.Entry<Ioc,Integer> e:counts.entrySet())if(e.getValue()>1)out.add(e.getKey());return out;}}
